From 804c52d7cf47c0a170a7ae8dee1199c4fd3eb959 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:06:18 +0100
Subject: [PATCH] applet, kcm: show LE Audio devices as audio devices

Devices that only offer LE Audio don't list the classic A2DP profile, so
uncategorized ones were shown as "Other device" in the applet and the
settings page. Also count the LE Audio capabilities service as audio.

BUG: 479620
---
 src/applet/qml/DeviceItem.qml | 3 ++-
 src/kcm/ui/script.js          | 3 ++-
 2 files changed, 4 insertions(+), 2 deletions(-)

diff --git a/src/applet/qml/DeviceItem.qml b/src/applet/qml/DeviceItem.qml
index e750926a..72ad59e9 100644
--- a/src/applet/qml/DeviceItem.qml
+++ b/src/applet/qml/DeviceItem.qml
@@ -306,7 +306,8 @@ PlasmaExtras.ExpandableListItem {
             if (model.Uuids.indexOf(BluezQt.Services.HumanInterfaceDevice) !== -1) {
                 profiles.push(i18n("Input"));
             }
-            if (model.Uuids.indexOf(BluezQt.Services.AdvancedAudioDistribution) !== -1) {
+            if (model.Uuids.indexOf(BluezQt.Services.AdvancedAudioDistribution) !== -1
+                || model.Uuids.indexOf(BluezQt.Services.PublishedAudioCapabilities.toUpperCase()) !== -1) {
                 profiles.push(i18n("Audio"));
             }
             if (model.Uuids.indexOf(BluezQt.Services.Nap) !== -1) {
diff --git a/src/kcm/ui/script.js b/src/kcm/ui/script.js
index 3dc3811e..a64f21d4 100644
--- a/src/kcm/ui/script.js
+++ b/src/kcm/ui/script.js
@@ -58,7 +58,8 @@ function deviceTypeToString(device) {
         if (uuids.includes(BluezQt.Services.HumanInterfaceDevice)) {
             profiles.push(i18n("Input"));
         }
-        if (uuids.includes(BluezQt.Services.AdvancedAudioDistribution)) {
+        if (uuids.includes(BluezQt.Services.AdvancedAudioDistribution)
+            || uuids.includes(BluezQt.Services.PublishedAudioCapabilities.toUpperCase())) {
             profiles.push(i18n("Audio"));
         }
         if (uuids.includes(BluezQt.Services.Nap)) {
-- 
